import React from 'react';
import { Download, MessageSquare } from 'lucide-react';
import { Language, ProductCategory } from '../types';
import { SITE_ORIGIN, categorySlug } from '../routing';

/** PDF files live in /public/catalogue/ and are generated by scripts/build-catalogue-pdf.ps1.
 *  With a range: that range's short catalogue (its models and installation steps). */
export const cataloguePdfPath = (lang: Language, range?: ProductCategory) =>
  range ? `/catalogue/birlik-catalogue-${categorySlug(range)}-${lang}.pdf` : `/catalogue/birlik-catalogue-${lang}.pdf`;

const TEXT = {
  ar: {
    title: 'حمّل الكتالوج الكامل (PDF)',
    body: 'كل الموديلات مع الصور والمقاسات في ملف واحد — سهل المشاركة على واتساب مع العائلة أو المهندس أو المعلّم.',
    download: 'تحميل الكتالوج PDF',
    share: 'مشاركة على واتساب',
    shareMsg: 'كتالوج شركة بيرليك لمواد الإكساء في اللاذقية:',
  },
  en: {
    title: 'Download the full catalogue (PDF)',
    body: 'Every model with photos and sizes in one file — easy to share on WhatsApp with family, your engineer or installer.',
    download: 'Download PDF catalogue',
    share: 'Share on WhatsApp',
    shareMsg: 'Birlik Company catalogue (Lattakia):',
  },
  tr: {
    title: 'Kataloğun tamamını indirin (PDF)',
    body: 'Tüm modeller fotoğraf ve ölçüleriyle tek dosyada — WhatsApp ile kolayca paylaşın.',
    download: 'PDF kataloğu indir',
    share: "WhatsApp'ta paylaş",
    shareMsg: 'Birlik Şirketi kataloğu (Lazkiye):',
  },
};

export const CatalogueDownload: React.FC<{ currentLang: Language }> = ({ currentLang }) => {
  const t = TEXT[currentLang];
  const pdfUrl = `${SITE_ORIGIN}${cataloguePdfPath(currentLang)}`;
  const shareUrl = `https://wa.me/?text=${encodeURIComponent(`${t.shareMsg} ${pdfUrl}`)}`;
  return (
    <section className="max-w-7xl mx-auto px-5 sm:px-6 lg:px-8 pb-16" data-reveal>
      <div className="rounded-3xl bg-ink text-white p-6 sm:p-9 flex flex-col sm:flex-row sm:items-center gap-5 justify-between">
        <div className="max-w-xl">
          <h2 className="text-xl sm:text-2xl font-bold mb-2">{t.title}</h2>
          <p className="text-sm text-[#E5DFD5] leading-relaxed">{t.body}</p>
        </div>
        <div className="flex flex-col gap-2.5 shrink-0">
          <a
            href={cataloguePdfPath(currentLang)}
            download
            className="inline-flex items-center justify-center gap-2 px-6 py-3.5 rounded-full bg-brass hover:bg-brass-light text-ink font-extrabold text-sm transition-colors"
          >
            <Download className="w-4 h-4" />
            {t.download}
          </a>
          <a
            href={shareUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center justify-center gap-2 px-6 py-3.5 rounded-full bg-wa hover:bg-wa-deep text-white font-bold text-sm transition-colors"
          >
            <MessageSquare className="w-4 h-4" />
            {t.share}
          </a>
        </div>
      </div>
    </section>
  );
};
